#[test]
fn hash_dedup_smoke() {
	let mut d = HashDataset::new();
	let q = Quad(
		LocalTerm::iri(iri_rs::IriBuf::from(iri!("http://example.com/s"))),
		LocalTerm::iri(iri_rs::IriBuf::from(iri!("http://example.com/p"))),
		LocalTerm::iri(iri_rs::IriBuf::from(iri!("http://example.com/o"))),
		None,
	);
	assert!(d.insert(q.clone()));
	assert!(!d.insert(q));
	assert_eq!(d.len(), 1);
}
